  "Camouflage": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":20,"priority":0,"target":"self","flags":{"snatch":1,"metronome":1},"desc":"The user's type changes based on the battle terrain. Normal type on the regular Wi-Fi terrain, Electric type during Electric Terrain, Fairy type during Misty Terrain, and Grass type during Grassy Terrain. Fails if the user's type cannot be changed or if the user is already purely that type.","shortDesc":"Changes user's type by terrain (default Normal)."},
