  "Circle Throw": {"power":60,"acc":90,"cat":"Physical","type":"Fighting","pp":10,"priority":-6,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1,"noassist":1,"failcopycat":1},"forceSwitch":true,"desc":"If both the user and the target have not fainted, the target is forced to switch out and be replaced with a random unfainted ally. This effect fails if the target is under the effect of Ingrain, has the Suction Cups Ability, or this move hit a substitute.","shortDesc":"Forces the target to switch to a random ally."},
  "Clamp": {"power":35,"acc":85,"cat":"Physical","type":"Water","pp":15,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"volatileStatus":"partiallytrapped","desc":"Prevents the target from switching for four or five turns (seven turns if the user is holding Grip Claw). Causes damage to the target equal to 1/8 of its maximum HP (1/6 if the user is holding Binding Band), rounded down, at the end of each turn during effect. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Parting Shot, U-turn, or Volt Switch. The effect ends if either the user or the target leaves the field, or if the target uses Rapid Spin or Substitute successfully. This effect is not stackable or reset by using this or another binding move.","shortDesc":"Traps and damages the target for 4-5 turns."},
