  "Conversion": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":30,"priority":0,"target":"self","flags":{"snatch":1,"metronome":1},"desc":"The user's type changes to match the original type of the move in its first move slot. Fails if the user cannot change its type, or if the type is one of the user's current types.","shortDesc":"Changes user's type to match its first move."},
  "Conversion 2": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":30,"priority":0,"target":"normal","flags":{"bypasssub":1,"metronome":1},"desc":"The user's type changes to match a type that resists or is immune to the type of the last move used by the target, but not either of its current types. The determined type of the move is used rather than the original type. Fails if the target has not made a move, if the user cannot change its type, or if this move would only be able to select one of the user's current types.","shortDesc":"Changes user's type to resist target's last move."},
  "Copycat": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":20,"priority":0,"target":"self","flags":{"noassist":1,"failcopycat":1,"nosleeptalk":1},"callsMove":true,"desc":"The user uses the last move used by any Pokemon, including itself. Fails if no move has been used, or if the last move used was Assist, Belch, Bestow, Celebrate, Chatter, Circle Throw, Copycat, Counter, Covet, Destiny Bond, Detect, Dragon Tail, Endure, Feint, Focus Punch, Follow Me, Helping Hand, Hold Hands, King's Shield, Mat Block, Me First, Metronome, Mimic, Mirror Coat, Mirror Move, Nature Power, Protect, Rage Powder, Roar, Sketch, Sleep Talk, Snatch, Spiky Shield, Struggle, Switcheroo, Thief, Transform, Trick, or Whirlwind.","shortDesc":"Uses the last move used in the battle."},
