  "Crush Claw": {"power":75,"acc":95,"cat":"Physical","type":"Normal","pp":10,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":50,"boosts":{"def":-1}},"desc":"Has a 50% chance to lower the target's Defense by 1 stage.","shortDesc":"50% chance to lower the target's Defense by 1."},
  "Crush Grip": {"power":0,"acc":100,"cat":"Physical","type":"Normal","pp":5,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"desc":"Power is equal to 120 * (target's current HP / target's maximum HP), rounded half down, but not less than 1.","shortDesc":"More power the more HP the target has left."},
  "Curse": {"power":0,"acc":null,"cat":"Status","type":"Ghost","pp":10,"priority":0,"target":"normal","flags":{"bypasssub":1,"metronome":1},"volatileStatus":"curse","desc":"If the user is not a Ghost type, lowers the user's Speed by 1 stage and raises the user's Attack and Defense by 1 stage. If the user is a Ghost type, the user loses 1/2 of its maximum HP, rounded down and even if it would cause fainting, in exchange for the target losing 1/4 of its maximum HP, rounded down, at the end of each turn while it is active. If the target uses Baton Pass, the replacement will continue to be affected. Fails if there is no target or if the target is already affected.","shortDesc":"Curses if Ghost, else -1 Spe, +1 Atk, +1 Def."},
