  "Defog": {"power":0,"acc":null,"cat":"Status","type":"Flying","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"reflectable":1,"mirror":1,"bypasssub":1,"metronome":1},"desc":"Lowers the target's evasiveness by 1 stage. If this move is successful and whether or not the target's evasiveness was affected, the effects of Reflect, Light Screen, Safeguard, Mist, Spikes, Toxic Spikes, Stealth Rock, and Sticky Web end for the target's side, and the effects of Spikes, Toxic Spikes, Stealth Rock, and Sticky Web end for the user's side. Ignores a target's substitute, although a substitute will still block the lowering of evasiveness.","shortDesc":"-1 evasion; clears user and target side's hazards."},
