  "Detect": {"power":0,"acc":null,"cat":"Status","type":"Fighting","pp":5,"priority":4,"target":"self","flags":{"noassist":1,"failcopycat":1},"volatileStatus":"protect","stallingMove":true,"desc":"The user is protected from most attacks made by other Pokemon during this turn. This move has a 1/X chance of being successful, where X starts at 1 and triples each time this move is successfully used. X resets to 1 if this move fails, if the user's last move used is not Detect, Endure, King's Shield, Protect, Quick Guard, Spiky Shield, or Wide Guard, or if it was one of those moves and the user's protection was broken. Fails if the user moves last this turn.","shortDesc":"Prevents moves from affecting the user this turn."},
