  "Dragon Rush": {"power":100,"acc":75,"cat":"Physical","type":"Dragon","pp":10,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1,"minimize":1},"secondary":{"chance":20,"volatileStatus":"flinch"},"desc":"Has a 20% chance to make the target flinch. Damage doubles and no accuracy check is done if the target has used Minimize while active.","shortDesc":"20% chance to make the target flinch."},
