  "Ice Burn": {"power":140,"acc":90,"cat":"Special","type":"Ice","pp":5,"priority":0,"target":"normal","flags":{"charge":1,"protect":1,"mirror":1,"nosleeptalk":1,"failinstruct":1},"secondary":{"chance":30,"status":"brn"},"desc":"Has a 30% chance to burn the target. This attack charges on the first turn and executes on the second. If the user is holding a Power Herb, the move completes in one turn.","shortDesc":"Charges turn 1. Hits turn 2. 30% burn."},
