  "Infestation": {"power":20,"acc":100,"cat":"Special","type":"Bug","pp":20,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"volatileStatus":"partiallytrapped","desc":"Prevents the target from switching for four or five turns (seven turns if the user is holding Grip Claw). Causes damage to the target equal to 1/8 of its maximum HP (1/6 if the user is holding Binding Band), rounded down, at the end of each turn during effect. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Parting Shot, U-turn, or Volt Switch. The effect ends if either the user or the target leaves the field, or if the target uses Rapid Spin or Substitute successfully. This effect is not stackable or reset by using this or another binding move.","shortDesc":"Traps and damages the target for 4-5 turns."},
  "Ingrain": {"power":0,"acc":null,"cat":"Status","type":"Grass","pp":20,"priority":0,"target":"self","flags":{"snatch":1,"nonsky":1,"metronome":1},"volatileStatus":"ingrain","desc":"The user has 1/16 of its maximum HP restored at the end of each turn, but it is prevented from switching out and other Pokemon cannot force the user to switch out. The user can still switch out if it uses Baton Pass, Parting Shot, U-turn, or Volt Switch. If the user leaves the field using Baton Pass, the replacement will remain trapped and still receive the healing effect. During the effect, the user can be hit normally by Ground-type attacks and be affected by Spikes, Toxic Spikes, and Sticky Web, even if the user is a Flying type or has the Levitate Ability.","shortDesc":"Traps/grounds user; heals 1/16 max HP per turn."},
  "Instruct": {"power":0,"acc":null,"cat":"Status","type":"Psychic","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"bypasssub":1,"allyanim":1,"failinstruct":1},"desc":"The target immediately uses its last used move again, at the same target. Fails if the target has not made a move, if the move has 0 PP or can't be chosen now, if it is a charging, recharging, locking or move-calling move, Bide, Focus Punch, Beak Blast, Shell Trap, Transform, Sketch, Struggle or Instruct, or if the target is in Bide or carried by Sky Drop.","shortDesc":"The target uses its last used move again."},
