  "Light Screen": {"power":0,"acc":null,"cat":"Status","type":"Psychic","pp":30,"priority":0,"target":"allySide","flags":{"snatch":1,"metronome":1},"sideCondition":"lightscreen","desc":"For 5 turns, the user and its party members take 0.5x damage from special attacks, or 0.66x damage if in a Double or Triple Battle. Critical hits ignore this effect. It is removed from the user's side if the user or an ally is successfully hit by Brick Break or Defog. Lasts for 8 turns if the user is holding Light Clay. Fails if the effect is already active on the user's side.","shortDesc":"For 5 turns, special damage to allies is halved."},
  "Lock-On": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":5,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"desc":"Until the end of the next turn, the target cannot avoid the user's moves, even if the target is in the middle of a two-turn move. The effect ends if either the user or the target leaves the field. Fails if this effect is active for the user.","shortDesc":"User's next move will not miss the target."},
