  "Lunar Dance": {"power":0,"acc":null,"cat":"Status","type":"Psychic","pp":10,"priority":0,"target":"self","flags":{"snatch":1,"dance":1,"heal":1,"metronome":1},"selfdestruct":"ifHit","slotCondition":"lunardance","desc":"The user faints and the Pokemon brought out to replace it has its HP and PP fully restored along with having any non-volatile status condition cured. The new Pokemon is sent out at the end of the turn, and the healing happens before hazards take effect. Fails if the user is the last unfainted Pokemon in its party.","shortDesc":"User faints. Replacement is fully healed, with PP."},
  "Luster Purge": {"power":70,"acc":100,"cat":"Special","type":"Psychic","pp":5,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":50,"boosts":{"spd":-1}},"desc":"Has a 50% chance to lower the target's Special Defense by 1 stage.","shortDesc":"50% chance to lower the target's Sp. Def by 1."},
