  "Magic Room": {"power":0,"acc":null,"cat":"Status","type":"Psychic","pp":10,"priority":0,"target":"all","flags":{"mirror":1,"metronome":1},"pseudoWeather":"magicroom","desc":"For 5 turns, the held items of all active Pokemon have no effect. An item's effect of causing forme changes is unaffected, but any other effects from such items are negated. During the effect, Fling and Natural Gift are prevented from being used by all active Pokemon. If this move is used during the effect, the effect ends.","shortDesc":"For 5 turns, all held items have no effect."},
  "Magical Leaf": {"power":60,"acc":null,"cat":"Special","type":"Grass","pp":20,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"desc":"This move does not check accuracy.","shortDesc":"This move does not check accuracy."},
  "Magma Storm": {"power":100,"acc":75,"cat":"Special","type":"Fire","pp":5,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"volatileStatus":"partiallytrapped","desc":"Prevents the target from switching for four or five turns (seven turns if the user is holding Grip Claw). Causes damage to the target equal to 1/8 of its maximum HP (1/6 if the user is holding Binding Band), rounded down, at the end of each turn during effect. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Parting Shot, U-turn, or Volt Switch. The effect ends if either the user or the target leaves the field, or if the target uses Rapid Spin or Substitute successfully. This effect is not stackable or reset by using this or another binding move.","shortDesc":"Traps and damages the target for 4-5 turns."},
  "Magnet Bomb": {"power":60,"acc":null,"cat":"Physical","type":"Steel","pp":20,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1,"bullet":1},"desc":"This move does not check accuracy.","shortDesc":"This move does not check accuracy."},
  "Magnet Rise": {"power":0,"acc":null,"cat":"Status","type":"Electric","pp":10,"priority":0,"target":"self","flags":{"snatch":1,"gravity":1,"metronome":1},"volatileStatus":"magnetrise","desc":"For 5 turns, the user is immune to Ground-type attacks and the effects of Spikes, Toxic Spikes, Sticky Web, and the Arena Trap Ability as long as it remains active. If the user uses Baton Pass, the replacement will gain the effect. Ingrain, Smack Down, Thousand Arrows, and Iron Ball override this move if the user is under any of their effects. Fails if the user is already under this effect or the effects of Ingrain, Smack Down, or Thousand Arrows.","shortDesc":"For 5 turns, the user has immunity to Ground."},
  "Magnetic Flux": {"power":0,"acc":null,"cat":"Status","type":"Electric","pp":20,"priority":0,"target":"allySide","flags":{"snatch":1,"distance":1,"bypasssub":1,"metronome":1},"desc":"Raises the Defense and Special Defense of Pokemon on the user's side with the Plus or Minus Abilities by 1 stage.","shortDesc":"Raises Def, Sp. Def of allies with Plus/Minus by 1."},
