  "Mat Block": {"power":0,"acc":null,"cat":"Status","type":"Fighting","pp":10,"priority":0,"target":"allySide","flags":{"snatch":1,"nonsky":1,"noassist":1,"failcopycat":1},"stallingMove":true,"sideCondition":"matblock","desc":"The user and its party members are protected from damaging attacks made by other Pokemon, including allies, during this turn. Fails unless it is the user's first turn on the field, if the user moves last this turn, or if this move is already in effect for the user's side.","shortDesc":"Protects allies from damaging attacks. Turn 1 only."},
  "Me First": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":20,"priority":0,"target":"adjacentFoe","flags":{"protect":1,"bypasssub":1,"noassist":1,"failcopycat":1,"failmefirst":1,"nosleeptalk":1},"callsMove":true,"desc":"The user uses the move the target chose for use this turn against it, if possible, with its power multiplied by 1.5. The move must be a damaging move other than Belch, Chatter, Counter, Covet, Focus Punch, Me First, Metal Burst, Mirror Coat, Struggle, or Thief. Fails if the target moves before the user. Ignores the target's substitute for the purpose of copying the move.","shortDesc":"Copies a foe at 1.5x power. User must be faster."},
  "Mean Look": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":5,"priority":0,"target":"normal","flags":{"reflectable":1,"mirror":1,"metronome":1},"desc":"Prevents the target from switching out. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Parting Shot, U-turn, or Volt Switch. If the target leaves the field using Baton Pass, the replacement will remain trapped. The effect ends if the user leaves the field.","shortDesc":"Prevents the target from switching out."},
