  "Nightmare": {"power":0,"acc":100,"cat":"Status","type":"Ghost","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"volatileStatus":"nightmare","desc":"Causes the target to lose 1/4 of its maximum HP, rounded down, at the end of each turn as long as it is asleep. This move does not affect the target unless it is asleep. The effect ends when the target wakes up, even if it falls asleep again in the same turn.","shortDesc":"A sleeping target is hurt by 1/4 max HP per turn."},
