  "Ominous Wind": {"power":60,"acc":100,"cat":"Special","type":"Ghost","pp":5,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":10,"self":{"boosts":{"atk":1,"def":1,"spa":1,"spd":1,"spe":1}}},"desc":"Has a 10% chance to raise the user's Attack, Defense, Special Attack, Special Defense, and Speed by 1 stage.","shortDesc":"10% chance to raise all stats by 1 (not acc/eva)."},
  "Origin Pulse": {"power":110,"acc":85,"cat":"Special","type":"Water","pp":10,"priority":0,"target":"allAdjacentFoes","flags":{"protect":1,"mirror":1,"pulse":1},"desc":"No additional effect.","shortDesc":"No additional effect. Hits adjacent foes."},
