  "Parabolic Charge": {"power":50,"acc":100,"cat":"Special","type":"Electric","pp":20,"priority":0,"target":"allAdjacent","flags":{"protect":1,"mirror":1,"heal":1,"metronome":1},"drain":[1,2],"desc":"The user recovers 1/2 the HP lost by the target, rounded half up. If Big Root is held by the user, the HP recovered is 1.3x normal, rounded half down.","shortDesc":"User recovers 50% of the damage dealt."},
  "Parting Shot": {"power":0,"acc":100,"cat":"Status","type":"Dark","pp":20,"priority":0,"target":"normal","flags":{"protect":1,"reflectable":1,"mirror":1,"sound":1,"bypasssub":1,"metronome":1},"selfSwitch":true,"desc":"Lowers the target's Attack and Special Attack by 1 stage. If this move is successful, the user switches out even if it is trapped and is replaced immediately by a selected party member. The user does not switch out if there are no unfainted party members.","shortDesc":"Lowers target's Atk, Sp. Atk by 1. User switches."},
  "Pay Day": {"power":40,"acc":100,"cat":"Physical","type":"Normal","pp":20,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"desc":"No additional effect.","shortDesc":"Scatters coins."},
