  "Rock Tomb": {"power":60,"acc":95,"cat":"Physical","type":"Rock","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":100,"boosts":{"spe":-1}},"desc":"Has a 100% chance to lower the target's Speed by 1 stage.","shortDesc":"100% chance to lower the target's Speed by 1."},
  "Rock Wrecker": {"power":150,"acc":90,"cat":"Physical","type":"Rock","pp":5,"priority":0,"target":"normal","flags":{"recharge":1,"protect":1,"mirror":1,"metronome":1,"bullet":1},"self":{"volatileStatus":"mustrecharge"},"desc":"If this move is successful, the user must recharge on the following turn and cannot select a move.","shortDesc":"User cannot move next turn."},
  "Role Play": {"power":0,"acc":null,"cat":"Status","type":"Psychic","pp":10,"priority":0,"target":"normal","flags":{"bypasssub":1,"allyanim":1,"metronome":1},"desc":"The user's Ability changes to match the target's Ability. Fails if the user's Ability is Multitype, Stance Change, or already matches the target, or if the target's Ability is Flower Gift, Forecast, Illusion, Imposter, Multitype, Stance Change, Trace, Wonder Guard, or Zen Mode.","shortDesc":"User replaces its Ability with the target's."},
  "Rolling Kick": {"power":60,"acc":85,"cat":"Physical","type":"Fighting","pp":15,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":30,"volatileStatus":"flinch"},"desc":"Has a 30% chance to make the target flinch.","shortDesc":"30% chance to make the target flinch."},
  "Rollout": {"power":30,"acc":90,"cat":"Physical","type":"Rock","pp":20,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1,"failinstruct":1,"noparentalbond":1},"desc":"If this move is successful, the user is locked into this move and cannot make another move until it misses, 5 turns have passed, or the attack cannot be used. Power doubles with each successful hit of this move and doubles again if Defense Curl was used previously by the user. If this move is called by Sleep Talk, the move is used for one turn.","shortDesc":"Power doubles with each hit. Repeats for 5 turns."},
  "Roost": {"power":0,"acc":null,"cat":"Status","type":"Flying","pp":10,"priority":0,"target":"self","flags":{"snatch":1,"heal":1,"metronome":1},"self":{"volatileStatus":"roost"},"desc":"The user restores 1/2 of its maximum HP, rounded half up. Until the end of the turn, Flying-type users lose their Flying type and pure Flying-type users become Normal type. Does nothing if the user's HP is full.","shortDesc":"Heals 50% HP. Flying-type removed 'til turn ends."},
  "Rototiller": {"power":0,"acc":null,"cat":"Status","type":"Ground","pp":10,"priority":0,"target":"all","flags":{"distance":1,"nonsky":1,"metronome":1},"desc":"Raises the Attack and Special Attack of all grounded Grass-type Pokemon on the field by 1 stage.","shortDesc":"Raises Atk/Sp. Atk of grounded Grass types by 1."},
  "Round": {"power":60,"acc":100,"cat":"Special","type":"Normal","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"sound":1,"bypasssub":1,"metronome":1},"desc":"If there are other active Pokemon that chose this move for use this turn, those Pokemon take their turn immediately after the user, in Speed order, and this move's power is 120 for each other user.","shortDesc":"Power doubles if others used Round this turn."},
  "Sacred Fire": {"power":100,"acc":95,"cat":"Physical","type":"Fire","pp":5,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"defrost":1,"metronome":1},"secondary":{"chance":50,"status":"brn"},"desc":"Has a 50% chance to burn the target.","shortDesc":"50% chance to burn the target. Thaws user."},
  "Sacred Sword": {"power":90,"acc":100,"cat":"Physical","type":"Fighting","pp":15,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1,"slicing":1},"ignoreDefensive":true,"ignoreEvasion":true,"desc":"Ignores the target's stat stage changes, including evasiveness.","shortDesc":"Ignores the target's stat stage changes."},
  "Safeguard": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":25,"priority":0,"target":"allySide","flags":{"snatch":1,"metronome":1},"sideCondition":"safeguard","desc":"For 5 turns, the user and its party members cannot have non-volatile status conditions or confusion inflicted on them by other Pokemon. Pokemon on the user's side cannot become affected by Yawn but can fall asleep from its effect. It is removed from the user's side if the user or an ally is successfully hit by Defog. Fails if the effect is already active on the user's side.","shortDesc":"For 5 turns, protects user's party from status."},
  "Sand Attack": {"power":0,"acc":100,"cat":"Status","type":"Ground","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"reflectable":1,"mirror":1,"metronome":1},"boosts":{"accuracy":-1},"desc":"Lowers the target's accuracy by 1 stage.","shortDesc":"Lowers the target's accuracy by 1."},
  "Sand Tomb": {"power":35,"acc":85,"cat":"Physical","type":"Ground","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"volatileStatus":"partiallytrapped","desc":"Prevents the target from switching for four or five turns (seven turns if the user is holding Grip Claw). Causes damage to the target equal to 1/8 of its maximum HP (1/6 if the user is holding Binding Band), rounded down, at the end of each turn during effect. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Parting Shot, U-turn, or Volt Switch. The effect ends if either the user or the target leaves the field, or if the target uses Rapid Spin or Substitute successfully. This effect is not stackable or reset by using this or another binding move.","shortDesc":"Traps and damages the target for 4-5 turns."},
  "Sandstorm": {"power":0,"acc":null,"cat":"Status","type":"Rock","pp":10,"priority":0,"target":"all","flags":{"metronome":1,"wind":1},"weather":"Sandstorm","desc":"For 5 turns, the weather becomes Sandstorm. At the end of each turn except the last, all active Pokemon lose 1/16 of their maximum HP, rounded down, unless they are a Ground, Rock, or Steel type, or have the Magic Guard, Overcoat, Sand Force, Sand Rush, or Sand Veil Abilities. During the effect, the Special Defense of Rock-type Pokemon is multiplied by 1.5 when taking damage from a special attack. Lasts for 8 turns if the user is holding Smooth Rock. Fails if the current weather is Sandstorm.","shortDesc":"For 5 turns, a sandstorm rages. Rock: 1.5x SpD."},
  "Scald": {"power":80,"acc":100,"cat":"Special","type":"Water","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"defrost":1,"metronome":1},"secondary":{"chance":30,"status":"brn"},"thawsTarget":true,"desc":"Has a 30% chance to burn the target. The target thaws out if it is frozen.","shortDesc":"30% chance to burn the target. Thaws target."},
