  "Searing Shot": {"power":100,"acc":100,"cat":"Special","type":"Fire","pp":5,"priority":0,"target":"allAdjacent","flags":{"protect":1,"mirror":1,"metronome":1,"bullet":1},"secondary":{"chance":30,"status":"brn"},"desc":"Has a 30% chance to burn the target.","shortDesc":"30% chance to burn adjacent Pokemon."},
  "Secret Power": {"power":70,"acc":100,"cat":"Physical","type":"Normal","pp":20,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":30,"status":"par"},"desc":"Has a 30% chance to cause a secondary effect on the target based on the battle terrain. Causes paralysis on the regular Wi-Fi terrain, causes paralysis during Electric Terrain, lowers Special Attack by 1 stage during Misty Terrain, and causes sleep during Grassy Terrain.","shortDesc":"Effect varies with terrain. (30% paralysis chance)"},
  "Secret Sword": {"power":85,"acc":100,"cat":"Special","type":"Fighting","pp":10,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"slicing":1},"overrideDefensiveStat":"def","desc":"Deals damage to the target based on its Defense instead of Special Defense.","shortDesc":"Damages target based on Defense, not Sp. Def."},
  "Seed Bomb": {"power":80,"acc":100,"cat":"Physical","type":"Grass","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1,"bullet":1},"desc":"No additional effect.","shortDesc":"No additional effect."},
