  "Seismic Toss": {"power":0,"acc":100,"cat":"Physical","type":"Fighting","pp":20,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"nonsky":1,"metronome":1},"desc":"Deals damage to the target equal to the user's level.","shortDesc":"Does damage equal to the user's level."},
  "Self-Destruct": {"power":200,"acc":100,"cat":"Physical","type":"Normal","pp":5,"priority":0,"target":"allAdjacent","flags":{"protect":1,"mirror":1,"metronome":1,"noparentalbond":1},"selfdestruct":"always","desc":"The user faints after using this move, even if this move fails for having no target. This move is prevented from executing if any active Pokemon has the Damp Ability.","shortDesc":"Hits adjacent Pokemon. The user faints."},
