  "Twister": {"power":40,"acc":100,"cat":"Special","type":"Dragon","pp":20,"priority":0,"target":"allAdjacentFoes","flags":{"protect":1,"mirror":1,"metronome":1,"wind":1},"secondary":{"chance":20,"volatileStatus":"flinch"},"desc":"Has a 20% chance to make the target flinch. Power doubles if the target is using Bounce, Fly, or Sky Drop, or is under the effect of Sky Drop.","shortDesc":"20% chance to make the foe(s) flinch."},
  "U-turn": {"power":70,"acc":100,"cat":"Physical","type":"Bug","pp":20,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"selfSwitch":true,"desc":"If this move is successful and the user has not fainted, the user switches out even if it is trapped and is replaced immediately by a selected party member. The user does not switch out if there are no unfainted party members, or if the target switched out using an Eject Button.","shortDesc":"User switches out after damaging the target."},
  "Uproar": {"power":90,"acc":100,"cat":"Special","type":"Normal","pp":10,"priority":0,"target":"randomNormal","flags":{"protect":1,"mirror":1,"sound":1,"bypasssub":1,"metronome":1,"nosleeptalk":1,"failinstruct":1},"self":{"volatileStatus":"uproar"},"desc":"The user spends three turns locked into this move. This move targets an adjacent opponent at random on each turn. On the first of the three turns, all sleeping active Pokemon wake up. During the three turns, no active Pokemon can fall asleep by any means, and Pokemon switched in during the effect do not wake up. If the user is prevented from moving or the attack is not successful against the target during one of the turns, the effect ends.","shortDesc":"Lasts 3 turns. Active Pokemon cannot fall asleep."},
  "V-create": {"power":180,"acc":95,"cat":"Physical","type":"Fire","pp":5,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1},"self":{"boosts":{"spe":-1,"def":-1,"spd":-1}},"desc":"Lowers the user's Speed, Defense, and Special Defense by 1 stage.","shortDesc":"Lowers the user's Defense, Sp. Def, Speed by 1."},
  "Vacuum Wave": {"power":40,"acc":100,"cat":"Special","type":"Fighting","pp":30,"priority":1,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"desc":"No additional effect.","shortDesc":"Usually goes first."},
