  "Venoshock": {"power":65,"acc":100,"cat":"Special","type":"Poison","pp":10,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"desc":"Power doubles if the target is poisoned.","shortDesc":"Power doubles if the target is poisoned."},
