  "Vise Grip": {"power":55,"acc":100,"cat":"Physical","type":"Normal","pp":30,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"desc":"No additional effect.","shortDesc":"No additional effect."},
  "Vital Throw": {"power":70,"acc":null,"cat":"Physical","type":"Fighting","pp":10,"priority":-1,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"desc":"This move does not check accuracy.","shortDesc":"This move does not check accuracy. Goes last."},
  "Volt Switch": {"power":70,"acc":100,"cat":"Special","type":"Electric","pp":20,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"selfSwitch":true,"desc":"If this move is successful and the user has not fainted, the user switches out even if it is trapped and is replaced immediately by a selected party member. The user does not switch out if there are no unfainted party members, or if the target switched out using an Eject Button.","shortDesc":"User switches out after damaging the target."},
  "Volt Tackle": {"power":120,"acc":100,"cat":"Physical","type":"Electric","pp":15,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":10,"status":"par"},"recoil":[33,100],"desc":"Has a 10% chance to paralyze the target. If the target lost HP, the user takes recoil damage equal to 33% the HP lost by the target, rounded half up, but not less than 1 HP.","shortDesc":"Has 33% recoil. 10% chance to paralyze target."},
  "Wake-Up Slap": {"power":70,"acc":100,"cat":"Physical","type":"Fighting","pp":10,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"desc":"Power doubles if the target is asleep. If the user has not fainted, the target wakes up.","shortDesc":"Power doubles if target is asleep, and wakes it."},
  "Water Gun": {"power":40,"acc":100,"cat":"Special","type":"Water","pp":25,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"desc":"No additional effect.","shortDesc":"No additional effect."},
  "Water Pledge": {"power":80,"acc":100,"cat":"Special","type":"Water","pp":10,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"nonsky":1,"metronome":1,"pledgecombo":1},"desc":"If one of the user's allies chose to use Fire Pledge or Grass Pledge this turn and has not moved yet, it takes its turn immediately after the user and the user's move does nothing. If combined with Fire Pledge, the ally uses Water Pledge with 150 power and a rainbow appears on the user's side for 4 turns, which doubles secondary effect chances and stacks with the Serene Grace Ability, except effects that cause flinching can only have their chance doubled once. If combined with Grass Pledge, the ally uses Grass Pledge with 150 power and a swamp appears on the target's side for 4 turns, which quarters the Speed of each Pokemon on that side. When used as a combined move, this move gains STAB no matter what the user's type is. This move does not consume the user's Water Gem, and cannot be redirected by the Storm Drain Ability.","shortDesc":"Use with Grass or Fire Pledge for added effect."},
