  "Water Shuriken": {"power":15,"acc":100,"cat":"Physical","type":"Water","pp":20,"priority":1,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"multihit":[2,5],"desc":"Hits two to five times. Has a 35% chance to hit two or three times and a 15% chance to hit four or five times. If one of the hits breaks the target's substitute, it will take damage for the remaining hits. If the user has the Skill Link Ability, this move will always hit five times.","shortDesc":"Usually goes first. Hits 2-5 times in one turn."},
