  "Water Spout": {"power":150,"acc":100,"cat":"Special","type":"Water","pp":5,"priority":0,"target":"allAdjacentFoes","flags":{"protect":1,"mirror":1,"metronome":1},"desc":"Power is equal to (user's current HP * 150 / user's maximum HP), rounded down, but not less than 1.","shortDesc":"Less power as user's HP decreases. Hits foe(s)."},
  "Waterfall": {"power":80,"acc":100,"cat":"Physical","type":"Water","pp":15,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"secondary":{"chance":20,"volatileStatus":"flinch"},"desc":"Has a 20% chance to make the target flinch.","shortDesc":"20% chance to make the target flinch."},
  "Weather Ball": {"power":50,"acc":100,"cat":"Special","type":"Normal","pp":10,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1,"bullet":1},"desc":"Power doubles if a weather condition other than Delta Stream is active, and this move's type changes to match. Ice type during Hail, Water type during Primordial Sea or Rain Dance, Rock type during Sandstorm, and Fire type during Desolate Land or Sunny Day. If the user is holding Utility Umbrella and uses Weather Ball during Primordial Sea, Rain Dance, Desolate Land, or Sunny Day, this move remains Normal type and does not double in power.","shortDesc":"Power doubles and type varies in each weather."},
  "Whirlpool": {"power":35,"acc":85,"cat":"Special","type":"Water","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"mirror":1,"metronome":1},"volatileStatus":"partiallytrapped","desc":"Prevents the target from switching for four or five turns (seven turns if the user is holding Grip Claw). Causes damage to the target equal to 1/8 of its maximum HP (1/6 if the user is holding Binding Band), rounded down, at the end of each turn during effect. The target can still switch out if it is holding Shed Shell or uses Baton Pass, Parting Shot, U-turn, or Volt Switch. The effect ends if either the user or the target leaves the field, or if the target uses Rapid Spin or Substitute successfully. This effect is not stackable or reset by using this or another binding move.","shortDesc":"Traps and damages the target for 4-5 turns."},
  "Whirlwind": {"power":0,"acc":null,"cat":"Status","type":"Normal","pp":20,"priority":-6,"target":"normal","flags":{"reflectable":1,"mirror":1,"bypasssub":1,"allyanim":1,"metronome":1,"noassist":1,"failcopycat":1,"wind":1},"forceSwitch":true,"desc":"The target is forced to switch out and be replaced with a random unfainted ally. Fails if the target is the last unfainted Pokemon in its party, or if the target used Ingrain previously or has the Suction Cups Ability.","shortDesc":"Forces the target to switch to a random ally."},
  "Wide Guard": {"power":0,"acc":null,"cat":"Status","type":"Rock","pp":10,"priority":3,"target":"allySide","flags":{"snatch":1},"sideCondition":"wideguard","desc":"The user and its party members are protected from damaging attacks made by other Pokemon, including allies, during this turn that target all adjacent foes or all adjacent Pokemon. This move modifies the same 1/X chance of being successful used by other protection moves, where X starts at 1 and triples each time this move is successfully used, but does not use the chance to check for failure. X resets to 1 if this move fails, if the user's last move used is not Detect, Endure, King's Shield, Protect, Quick Guard, Spiky Shield, or Wide Guard, or if it was one of those moves and the user's protection was broken. Fails if the user moves last this turn or if this move is already in effect for the user's side.","shortDesc":"Protects allies from multi-target damage this turn."},
  "Wild Charge": {"power":90,"acc":100,"cat":"Physical","type":"Electric","pp":15,"priority":0,"target":"normal","flags":{"contact":1,"protect":1,"mirror":1,"metronome":1},"recoil":[1,4],"desc":"If the target lost HP, the user takes recoil damage equal to 1/4 the HP lost by the target, rounded half up, but not less than 1 HP.","shortDesc":"Has 1/4 recoil."},
  "Will-O-Wisp": {"power":0,"acc":85,"cat":"Status","type":"Fire","pp":15,"priority":0,"target":"normal","flags":{"protect":1,"reflectable":1,"mirror":1,"metronome":1},"status":"brn","desc":"Burns the target.","shortDesc":"Burns the target."},
  "Wing Attack": {"power":60,"acc":100,"cat":"Physical","type":"Flying","pp":35,"priority":0,"target":"any","flags":{"contact":1,"protect":1,"mirror":1,"distance":1,"metronome":1},"desc":"No additional effect.","shortDesc":"No additional effect."},
