  "Withdraw": {"power":0,"acc":null,"cat":"Status","type":"Water","pp":40,"priority":0,"target":"self","flags":{"snatch":1,"metronome":1},"boosts":{"def":1},"desc":"Raises the user's Defense by 1 stage.","shortDesc":"Raises the user's Defense by 1."},
  "Wonder Room": {"power":0,"acc":null,"cat":"Status","type":"Psychic","pp":10,"priority":0,"target":"all","flags":{"mirror":1,"metronome":1},"pseudoWeather":"wonderroom","desc":"For 5 turns, all active Pokemon have their Defense and Special Defense stats swapped. Stat stage changes are unaffected. If this move is used during the effect, the effect ends.","shortDesc":"For 5 turns, all Defense and Sp. Def stats switch."},
