  "Shadow Break": {"power":75,"acc":100,"cat":"Physical","type":"Shadow","pp":5,"priority":0,"target":"normal","flags":{"protect":1},"shadow":1,"desc":"A Shadow move: no PP. Super effective on non-Shadow Pokémon, not very effective on Shadow Pokémon.","shortDesc":"Hits one foe."},
