  "Shadow Wave": {"power":50,"acc":100,"cat":"Special","type":"Shadow","pp":5,"priority":0,"target":"allAdjacentFoes","flags":{"protect":1},"shadow":1,"desc":"A Shadow move: no PP. Hits both foes.","shortDesc":"Hits both foes."},
  "Shadow Rave": {"power":70,"acc":100,"cat":"Special","type":"Shadow","pp":5,"priority":0,"target":"allAdjacentFoes","flags":{"protect":1},"shadow":1,"desc":"A Shadow move: no PP. Hits both foes.","shortDesc":"Hits both foes."},
