  "Shadow Blast": {"power":80,"acc":100,"cat":"Physical","type":"Shadow","pp":5,"priority":0,"target":"normal","flags":{"protect":1},"shadow":1,"critRatio":2,"desc":"A Shadow move: no PP. A vacuum blade with a high critical hit ratio.","shortDesc":"High critical hit ratio."},
